import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './Auth.css';

const Auth = () => {
  const [isLogin, setIsLogin] = useState(true);
  const navigate = useNavigate();

  const switchModeHandler = () => {
    setIsLogin(prevState => !prevState);
  };

  const submitHandler = (event) => {
    event.preventDefault();
    // In a real application, you would have your login/signup logic here.
    // After a successful login/signup, you would navigate.
    console.log('Form submitted!');
    navigate('/');
  };

  return (
    <div className="auth-page">
      <div className="auth-form-container">
        <h2>{isLogin ? 'Login' : 'Sign Up'}</h2>
        <form onSubmit={submitHandler}>
          {!isLogin && (
            <div className="form-control">
              <label htmlFor="name">Name</label>
              <input type="text" id="name" required />
            </div>
          )}
          <div className="form-control">
            <label htmlFor="email">Email</label>
            <input type="email" id="email" required />
          </div>
          <div className="form-control">
            <label htmlFor="password">Password</label>
            <input type="password" id="password" required />
          </div>
          <div className="form-actions">
            <button type="submit">{isLogin ? 'Login' : 'Create Account'}</button>
          </div>
        </form>
        <button onClick={switchModeHandler} className="switch-button">
          {isLogin ? "Don't have an account? Sign Up" : 'Have an account? Login'}
        </button>
      </div>
    </div>
  );
};

export default Auth;
